# BE-002 · Second concurrent writer is rejected (optimistic lock)
# Requirement: R5 · Priority: P1 · Suites: regression
# Concurrency
# Generated by the FlowPilot AI Test Factory (CogenSight)
import pytest


def test_optimistic_lock(client):
    etag = client.get("/api/customers/1").headers["etag"]
    a = client.put("/api/customers/1", json={"Phone": "1"}, headers={"If-Match": etag})
    b = client.put("/api/customers/1", json={"Phone": "2"}, headers={"If-Match": etag})
    assert a.status_code == 200
    assert b.status_code == 412
